import json,sys,base64,re,html
d=json.loads(json.load(open(sys.argv[1]))['result'])
def body(p):
    out=''
    if p.get('body',{}).get('data'):
        out+=base64.urlsafe_b64decode(p['body']['data']+'==').decode('utf8','replace')
    for q in p.get('parts',[]) or []:
        if q.get('mimeType','').startswith('text/plain') or q.get('parts'): out+=body(q)
    if not out:
        for q in p.get('parts',[]) or []: out+=body(q)
    return out
for m in d['messages']:
    h={x['name']:x['value'] for x in m['payload'].get('headers',[])}
    print('=====',h.get('Date'),'|',h.get('From'),'->',h.get('To'),'| cc',h.get('Cc'),'|',h.get('Subject'))
    b=body(m['payload'])
    b=re.sub(r'<[^>]+>',' ',b); b=html.unescape(b); b=re.sub(r'\s+\n','\n',b)
    print(b[:int(sys.argv[2]) if len(sys.argv)>2 else 1500])
